// ถอดคำตอบ MC Protocol แล้วเลือกค่าที่ต้องการ
const buf = msg.payload;
if (!Buffer.isBuffer(buf) || buf.length < 11) { node.status({fill:"red",shape:"ring",text:"ไม่มีคำตอบจาก PLC"}); return [null, msg]; }
const end = buf.readUInt16LE(9);
if (buf.readUInt16LE(0) !== 0x00D0 || end !== 0) {
    node.status({ fill: "red", shape: "ring", text: "PLC error 0x" + end.toString(16) });
    return [null, msg];
}
const w = i => buf.readUInt16LE(11 + i * 2);                 // D(i)
const d32 = i => w(i) + w(i + 1) * 65536;                    // BIN32: word ต่ำก่อน
if (buf.length < 11 + 332 * 2) { node.status({fill:"yellow",shape:"ring",text:"ข้อมูลไม่ครบ " + buf.length}); return [null, msg]; }

const total = d32(322), ng = w(60);
const out = {
    total:  total,                       // D322 入球總數 ยอดรวม (BIN32)
    ng:     ng,                          // D60  不良數量 NG (BIN16)
    ok:     Math.max(0, total - ng),     // คำนวณ = ยอดรวม - NG
    rate:   d32(330) / 10,               // D330 定位率 % (BIN32 /10)
    ccdNg:  d32(300),                    // D300 CCD 檢測異常 (BIN32)
    ccdOk:  w(320),                      // D320 CCD 檢測 OK (BIN16)
    status: w(0),                        // D0   1=OP 2=EG 3=SV
    statusText: { 1: "OP", 2: "EG", 3: "SV" }[w(0)] || ("?" + w(0)),
    time: new Date().toLocaleString("en-GB")
};
flow.set("sb01", out);
node.status({ fill: "green", shape: "dot", text: out.statusText + " | Total " + out.total + " NG " + out.ng + " | " + out.rate + "%" });
return [{ topic: "SB01", payload: out }, null];
